// Stub of qollab_project/observatory_api.py for local UI testing (dev/index.html maps
// the bare specifier "observatory_api" here with an import map). Same function names;
// each is a function with .callPromising(...) that resolves to a JSON string, like a
// Pyodide PyProxy. Canned answers come from dev/stub_data.js (generated by
// tools/make_ui_stubs.py from the REAL observatory_api functions). Settings without a
// canned run are synthesized here from the closed-form distributions with a seeded
// sampler and marked "[stub]" in the backend name and persona lines. Not uploaded.

import { STUB } from "./stub_data.js";

const params = new URLSearchParams(globalThis.location ? globalThis.location.search : "");
const SLOW = Number(params.get("slow") || 1);   // ?slow=3 triples every delay
const OUTCOMES = ["00", "01", "10", "11"];
const PROBES = ["display", "intent_low", "intent_high", "connection"];
const LN80 = Math.log(80);
let jobsThisLoad = 0;
let synthJobs = 0;

function asPy(fn, delayMs) {
  const f = (...args) => fn(...args);
  f.callPromising = (...args) => new Promise((resolve, reject) => {
    setTimeout(() => {
      try { resolve(fn(...args)); } catch (err) { reject(err); }
    }, delayMs * SLOW);
  });
  return f;
}

function kindOf(backend) {
  const k = backend && backend.stubKind;
  return k && STUB.profiles[k] ? k : "basic";
}

function fail(msg) {
  return { status: "failed", error: "ValueError: " + msg, model_version: STUB.model_version };
}

// ------------------------------------------------------------------ settings
function normalize(settingsJson) {
  const s = JSON.parse(settingsJson || "{}") || {};
  const num = (key, lo, hi, dflt) => {
    const v = s[key] === undefined || s[key] === null ? dflt : Number(s[key]);
    if (!Number.isFinite(v) || v < lo || v > hi + 1e-9) throw new Error(key + " must be in [" + lo + ", " + hi + "], got " + s[key]);
    return Math.min(Math.max(v, lo), hi);
  };
  const out = {
    intention_rad: num("intention_rad", 0, 2 * Math.PI, Math.PI / 2),
    world_coupling: num("world_coupling", 0, 1, 0),
    perspective_rad: num("perspective_rad", 0, Math.PI, 0),
    shots_per_probe: Math.round(num("shots_per_probe", 1, 4096, 1024)),
    persona: String(s.persona || "self"),
    mode: String(s.mode || "auto"),
    canary: s.canary === undefined ? true : !!s.canary,
  };
  out.gamma_rad = out.world_coupling * Math.PI / 2;
  return out;
}

function keyOf(s) {
  const deg = (r) => Math.round(r * 180 / Math.PI);
  return [deg(s.intention_rad), String(Number(s.world_coupling.toFixed(2))), deg(s.perspective_rad), s.shots_per_probe].join("|");
}

// ------------------------------------------------------------------ closed form
function probeDists(s) {
  const c = Math.cos(s.gamma_rad), sn = Math.sin(s.gamma_rad);
  const disp = (theta) => {
    const ct = Math.cos(theta);
    return { "00": (1 + c * c + 2 * c * ct) / 4, "01": sn * sn / 4, "10": (1 + c * c - 2 * c * ct) / 4, "11": sn * sn / 4 };
  };
  return {
    display: disp(s.intention_rad - s.perspective_rad),
    intent_low: disp(0),
    intent_high: disp(Math.PI),
    connection: { "00": 0.5, "01": 0, "10": c * c / 2, "11": sn * sn / 2 },
  };
}

function pSelf1(d) {
  const n = OUTCOMES.reduce((a, k) => a + (d[k] || 0), 0);
  return ((d["10"] || 0) + (d["11"] || 0)) / n;
}

function entropy(p) {
  let hh = 0;
  for (const q of [p, 1 - p]) if (q > 0) hh -= q * Math.log2(q);
  return hh;
}

function mutualInfo(d) {
  const n = OUTCOMES.reduce((a, k) => a + (d[k] || 0), 0);
  const p = {};
  for (const k of OUTCOMES) p[k] = (d[k] || 0) / n;
  const ps = { 0: p["00"] + p["01"], 1: p["10"] + p["11"] };
  const pw = { 0: p["00"] + p["10"], 1: p["01"] + p["11"] };
  let info = 0;
  for (const a of [0, 1]) for (const b of [0, 1]) {
    const j = p[String(a) + String(b)];
    if (j > 0) info += j * Math.log2(j / (ps[a] * pw[b]));
  }
  return Math.max(0, info);
}

function core(dists) {
  const p = pSelf1(dists.display), lo = pSelf1(dists.intent_low), hi = pSelf1(dists.intent_high);
  return { p_self_1: p, p_low: lo, p_high: hi, delta_signed: hi - lo, capacity: Math.abs(hi - lo),
    openness_bits: entropy(p), connection_bits: mutualInfo(dists.connection) };
}

function prediction(s) {
  const dists = probeDists(s);
  return Object.assign(core(dists), {
    formula_p_self_1: "P(Self=1) = [1 - cos(gamma) cos(phi - beta)] / 2, with gamma = w * pi / 2",
    p_self_1_closed_form: (1 - Math.cos(s.gamma_rad) * Math.cos(s.intention_rad - s.perspective_rad)) / 2,
    capacity_closed_form: Math.cos(s.gamma_rad),
    probe_distributions: dists,
    bit_order: "SelfWorld",
  });
}

// ------------------------------------------------------------------ seeded sampling
function hashKey(str) {
  let x = 2166136261;
  for (let i = 0; i < str.length; i++) { x ^= str.charCodeAt(i); x = Math.imul(x, 16777619); }
  return x >>> 0;
}

function mulberry32(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function sample(dist, shots, rand) {
  const out = { "00": 0, "01": 0, "10": 0, "11": 0 };
  const cum = [];
  let acc = 0;
  for (const k of OUTCOMES) { acc += dist[k]; cum.push(acc); }
  for (let i = 0; i < shots; i++) {
    const u = rand() * acc;
    let j = 0;
    while (j < 3 && u > cum[j]) j++;
    out[OUTCOMES[j]] += 1;
  }
  return out;
}

function metrics(counts) {
  const m = core(counts);
  const n = {};
  for (const p of PROBES) n[p] = OUTCOMES.reduce((a, k) => a + counts[p][k], 0);
  const e = Math.sqrt(LN80 / (2 * n.intent_low)) + Math.sqrt(LN80 / (2 * n.intent_high));
  const dlo = Math.max(-1, m.delta_signed - e), dhi = Math.min(1, m.delta_signed + e);
  let ci, resolved;
  if (dlo <= 0 && 0 <= dhi) { ci = [0, Math.max(Math.abs(dlo), Math.abs(dhi))]; resolved = false; }
  else { ci = [Math.min(Math.abs(dlo), Math.abs(dhi)), Math.max(Math.abs(dlo), Math.abs(dhi))]; resolved = true; }
  return Object.assign(m, { hoeffding_e: e, capacity_ci95: ci, resolved, shots_seen: n });
}

function nearestCanned(s) {
  let best = null, bestD = Infinity;
  for (const r of Object.values(STUB.runs.basic)) {
    const t = r.settings;
    const d = Math.abs(t.world_coupling - s.world_coupling) * 2 +
      Math.abs(Math.cos(t.intention_rad - t.perspective_rad) - Math.cos(s.intention_rad - s.perspective_rad));
    if (d < bestD) { bestD = d; best = r; }
  }
  return best;
}

function fix(x, d) {
  return Number(x).toFixed(d);
}

function synthesize(kind, s) {
  const template = nearestCanned(s);
  const dists = probeDists(s);
  const rand = mulberry32(hashKey(keyOf(s)) ^ 0x9e3779b9);
  const counts = {};
  for (const p of PROBES) counts[p] = sample(dists[p], s.shots_per_probe, rand);
  const m = metrics(counts);
  const pred = prediction(s);
  let factual = "With intention " + fix(s.intention_rad, 3) + " rad, World coupling " + fix(s.world_coupling, 2) + " and perspective " +
    fix(s.perspective_rad, 3) + " rad: measured P(Self=1) = " + fix(m.p_self_1, 3) + " (Demon forecast " + fix(pred.p_self_1, 3) + "); capacity " +
    fix(m.capacity, 3) + ", conservative 95% interval " + fix(m.capacity_ci95[0], 3) + " to " + fix(m.capacity_ci95[1], 3) + " (ideal " +
    fix(pred.capacity, 3) + "); openness " + fix(m.openness_bits, 3) + " bits; connection " + fix(m.connection_bits, 3) + " bits from the reference probe.";
  if (!m.resolved) factual += " No resolved influence at this shot count.";
  const poetic = {};
  for (const k of ["self", "demon", "observer"]) {
    poetic[k] = "[stub: persona line borrowed from the nearest canned run] " + template.explanation.poetic[k];
  }
  synthJobs += 1;
  const source = Object.assign({}, template.source, {
    backend_name: (STUB.profiles[kind].profile.name || "stub") + " [stub: JS closed-form sampler]",
    job_id: "stub-synth-" + synthJobs, job_returned: true, wall_s: 0.01, shots_requested: s.shots_per_probe,
    shots_seen: m.shots_seen, mode: STUB.profiles[kind].mode,
  });
  return { status: "completed", settings: s, source, bit_order: "SelfWorld", counts, metrics: m, prediction: pred,
    explanation: { factual, poetic, animation: template.explanation.animation, resolved: m.resolved, note: template.explanation.note }, baselines: template.baselines,
    model_version: STUB.model_version, jobs_submitted: jobsThisLoad, stub: "synthesized in JS from the closed form (seeded sampler)" };
}

// ------------------------------------------------------------------ exports
export const profile_json = asPy((backend, newRun) => {
  if (newRun === true) jobsThisLoad = 0;   // like observatory_api: main.js marks the start of a run
  const p = Object.assign({}, STUB.profiles[kindOf(backend)]);
  p.jobs_submitted = jobsThisLoad;
  return JSON.stringify(p);
}, 60);

export const predict_json = asPy((settingsJson) => {
  let s;
  try { s = normalize(settingsJson); } catch (err) { return JSON.stringify(fail(err.message)); }
  const canned = STUB.predicts[keyOf(s)];
  if (canned) return JSON.stringify(canned);
  const any = Object.values(STUB.predicts)[0];
  return JSON.stringify({ settings: s, ideal: prediction(s), noisy_ionq_like: null, baselines: any.baselines,
    model_version: STUB.model_version, stub: "computed in JS from the closed form (no IonQ-like forecast in stub mode)" });
}, 25);

export const run_json = asPy((backend, settingsJson) => {
  const kind = kindOf(backend);
  const profile = STUB.profiles[kind];
  let s;
  try { s = normalize(settingsJson); } catch (err) { return JSON.stringify(fail(err.message)); }
  if (profile.one_job && jobsThisLoad >= 1) return JSON.stringify(STUB.runs["ionq:refused"]);
  jobsThisLoad += 1;
  if (kind === "error") {
    const r = Object.assign({}, Object.values(STUB.runs.error)[0], { settings: s });
    return JSON.stringify(r);
  }
  const key = keyOf(s);
  const canned = (STUB.runs[kind] || {})[key] || (kind === "ionq" ? null : null);
  if (canned) {
    console.log("[stub] canned run " + key + " (real engine output under CPython)");
    return JSON.stringify(canned);
  }
  console.warn("[stub] no canned run for " + key + ": synthesized in JS from the closed form (seeded sampler)");
  return JSON.stringify(synthesize(kind, s));
}, 900);

export const explain_json = asPy((resultJson, persona) => {
  const r = JSON.parse(resultJson || "{}") || {};
  const e = r.explanation || {};
  const p = persona || "self";
  return JSON.stringify({ persona: p, factual: e.factual, poetic: (e.poetic || {})[p], poetic_all: e.poetic,
    resolved: e.resolved, note: e.note, model_version: STUB.model_version });
}, 20);

export const curves_json = asPy(() => JSON.stringify(STUB.curves), 80);
